#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
# Source the env.sh generated by vendor/FerroUI/scripts/browser/setup.sh first.
command -v emcc >/dev/null || { echo 'Activate the Emscripten SDK (see README.md).' >&2; exit 1; }
export EMCC_CFLAGS="${EMCC_CFLAGS:-} -s ERROR_ON_UNDEFINED_SYMBOLS=0"
cargo build --locked --target wasm32-unknown-emscripten --profile browser
webapp=vendor/FerroUI/src/Browser/FerroUI.Browser/webapp
if [ ! -d "$webapp/node_modules" ]; then (cd "$webapp" && npm ci --ignore-scripts); fi
(cd "$webapp" && npm run build)
mkdir -p dist
cp -R wwwroot/. dist/
cp vendor/FerroUI/src/Browser/FerroUI.Browser/dist/{ferroui.js,ferroui.js.map,storage.js,storage.js.map,ferroui-sw.js} dist/
cp vendor/FerroUI/scripts/browser/threads/ferroui-loader.js dist/
cp "${CARGO_TARGET_DIR:-target}/wasm32-unknown-emscripten/browser/ferro-store.js" dist/
cp "${CARGO_TARGET_DIR:-target}/wasm32-unknown-emscripten/browser/ferro_store.wasm" dist/
cp -R "${CARGO_TARGET_DIR:-target}/wasm32-unknown-emscripten/browser/deps/snippets" dist/
node scripts/compile-catalog.mjs
cp catalog/manifest.schema.json dist/manifest.schema.json
cp catalog/example.ferro-app.json dist/example.ferro-app.json
touch dist/.nojekyll
